    for (const id of ids) {
        const m = src.modes && src.modes[id];
        modes[id] = PROVIDER_MODES.includes(m) ? m : 'live';
    }
    const order = (Array.isArray(src.order) ? src.order : []).filter((id, i, a) => ids.includes(id) && a.indexOf(id) === i);
